.gsb.gsb-theme-light .gsb-excluded .gsb-rule-icon{background:#ffe4e6;color:#9f1239}
.gsb.gsb-theme-light .gsb-count{color:var(--_gs-on-accent)}
.gsb.gsb-theme-light .gsb-rule-remove{color:var(--_gs-muted)!important}
.gsb.gsb-theme-light .gsb-rule-remove:hover{color:#fff!important}
.gsb.gsb-theme-light .gsb-option.include .gsb-tristate{background:#dcfce7;color:#166534}
.gsb.gsb-theme-light .gsb-option.exclude .gsb-tristate{background:#ffe4e6;color:#9f1239}

/* v2.1: semantic token coverage for controls, rules, and popovers (both presets). */
.gsb .gsb-panel-button,.gsb .gsb-filter-trigger,.gsb .gsb-filter-field>select,.gsb .gsb-rule-token,.gsb .gsb-range-inputs input{background:var(--_gs-control);color:var(--_gs-text);border-color:var(--_gs-border-strong)}
.gsb .gsb-rule-box,.gsb .gsb-advanced,.gsb .gsb-search-line{background:var(--_gs-bg)}
.gsb .gsb-menu,.gsb .gsb-suggestions{background:var(--_gs-popover);color:var(--_gs-text)}
.gsb .gsb-panel-button.gsb-open,.gsb .gsb-group,.gsb .gsb-expanded-item{background:var(--_gs-accent-soft)}
.gsb .gsb-panel-button:hover,.gsb .gsb-option:hover,.gsb .gsb-filter-trigger:hover,.gsb .gsb-group:hover{background:var(--_gs-accent-hover)}
.gsb .gsb-rule-icon{background:color-mix(in srgb,var(--_gs-include) 18%,var(--_gs-surface));color:var(--_gs-include)}
.gsb .gsb-excluded .gsb-rule-icon{background:color-mix(in srgb,var(--_gs-exclude) 18%,var(--_gs-surface));color:var(--_gs-exclude)}
.gsb .gsb-group-field,.gsb .gsb-rule-move small,.gsb .gsb-suggestion-copy small{color:var(--_gs-muted)}
.gsb .gsb-shortcut{background:var(--_gs-accent-soft);color:var(--_gs-muted);border-color:var(--_gs-border)}
.gsb .gsb-search-button,.gsb .gsb-modes button.gsb-active{background:var(--_gs-accent);color:var(--_gs-on-accent)}
.gsb .gsb-search-line input::placeholder,.gsb .gsb-menu>input::placeholder{color:var(--gs-placeholder,var(--_gs-muted))}
.gsb .gsb-more,.gsb .gsb-clear-field{border-top-color:var(--_gs-border);color:var(--_gs-accent)}
.gsb .gsb-range-error{color:var(--_gs-exclude)}
